from typing import Literal, Union

from ...base.client import BaseClient

GalleryEntry = Literal["video", "image", "ptt", "file", "audio", "link"]
GalleryEntries = Union[list[GalleryEntry, GalleryEntry], tuple[GalleryEntry, GalleryEntry]]
FromEntryId = Union[Literal["max"], dict[str, Union[int, Literal["max"]]]]


class GalleryMethods(BaseClient):
    """
    Методы группы 'Галерея' из https://im-docs.corp.mail.ru/
    """

    async def rapi_getEntryGallery(
        self,
        sn: str,
        entriesInPatch: bool = True,
        subreqId: Literal["older", "newer"] = "older",
        fromEntryId: FromEntryId = "max",
        entryCount: int = -6,
        urlType: GalleryEntries = ("video", "image"),
    ):
        return await self.post(
            "rapi/getEntryGallery",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "sn": sn,
                    "entriesInPatch": entriesInPatch,
                    "subreqs": [
                        {
                            "subreqId": subreqId,
                            "fromEntryId": fromEntryId,
                            "entryCount": entryCount,
                            "urlType": urlType,
                        },
                    ],
                },
            },
        )
